function draw({board,width,height,progress,params}) {
  const P=VisualBook.palette, narrow=width<520, d=params.delta;
  const X=[[[0,1],[3,4]],[[1,2],[4,5]]], K=[[[0,1],[2,3]],[[1,2],[3,4]]];
  const partial=[], terms=[], Y=[];
  for(let m=0;m<3;m++) {
    terms[m]=X.map((a,c)=>a.flat().map((v,j)=>v*(K[c].flat()[j]+m*d)));
    partial[m]=terms[m].map(t=>t.reduce((a,b)=>a+b,0));
    Y[m]=partial[m][0]+partial[m][1];
  }
  const cell=narrow?29:32, inputY=42;
  const inputXs=narrow?[width*.20-cell,width*.65-cell]:[24,132];
  X.forEach((a,c)=>board.matrix('input-'+c,a,{x:inputXs[c],y:inputY,cell,label:'X'+c+' · 2×2',color:c?P.orange:P.blue,precision:0}));
  const top=narrow?176:85, dy=narrow?65:66;
  const labelX=narrow?13:width*.37, c0=narrow?width*.34:width*.51, c1=narrow?width*.58:width*.69, out=narrow?width*.86:width*.90;
  const fmt=v=>Number(v.toFixed(2)).toString();
  board.text('axis0','输入0',c0,top-24,{anchor:'middle',color:P.blue,size:13});
  board.text('axis1','输入1',c1,top-24,{anchor:'middle',color:P.orange,size:13});
  board.text('axisout','输出 m',out,top-24,{anchor:'middle',size:13});
  for(let m=0;m<3;m++) {
    const y=top+m*dy;
    board.text('kernel-'+m,m===0?'K':'K + '+(m===1?'δ':'2δ'),labelX,y+5,{size:14});
    board.line('sumline-'+m,c0-15,y+21,out,y+21,P.faint,1);
    board.text('a-'+m,fmt(partial[m][0]),c0,y+5,{anchor:'middle',color:P.blue,size:19});
    board.text('plus-'+m,'+', (c0+c1)/2,y+5,{anchor:'middle',color:P.muted,size:14});
    board.text('b-'+m,fmt(partial[m][1]),c1,y+5,{anchor:'middle',color:P.orange,size:19});
    board.text('equal-'+m,'=',(c1+out)/2-4,y+5,{anchor:'middle',color:P.muted,size:14});
    board.rect('output-box-'+m,out-24,y-17,48,36,P.paper,{stroke:P.ink,'stroke-width':1,'rx':3});
    board.text('value-'+m,fmt(Y[m]),out,y+6,{anchor:'middle',size:19});
    for(let c=0;c<2;c++) {
      const start=[inputXs[c]+cell,inputY+2*cell+8];
      const mid=[c?c1:c0,y+21], end=[out,y+21];
      const t=progress<.55?progress/.55:(progress-.55)/.45;
      const a=progress<.55?start:mid,b=progress<.55?mid:end;
      const q=a.map((v,j)=>v+(b[j]-v)*t);
      board.path('route-'+m+'-'+c,[start,mid,end],{color:P.faint,width:1,opacity:.7});
      board.circle('signal-'+m+'-'+c,q[0],q[1],3.5,c?P.orange:P.blue);
    }
  }
  board.line('stack-axis',out+29,top-17,out+29,top+2*dy+19,P.ink,1);
  board.text('stack-shape','Y[:,0,0] · 3个输出',width/2,narrow?395:313,{anchor:'middle',size:14});
  board.text('delta-effect','δ = '+fmt(d)+'   每组都读取两个输入通道',width/2,narrow?421:340,{anchor:'middle',color:P.muted,size:13});
  return {selectedInputPatch:X,kernelBase:K,delta:d,terms,partial,selectedOutput:Y,fullInputShape:[2,3,3],patchShape:[2,2,2],kernelShape:[3,2,2,2],selectedPixel:[0,0],readingProgress:progress};
}

function draw({board,width,height,progress,params}) {
  const P=VisualBook.palette, mobile=width<520, beta=params.beta;
  const K=[[1,beta,-1],[0,1,1]], X=[[1,2,3,4],[0,1,2,3],[2,0,1,2]], Y=VisualBook.matmul(K,X);
  const cell=mobile?29:32;
  const kx=mobile?12:24, ky=40, xx=mobile?width-4*cell-12:width*.32, xy=40;
  const yx=mobile?width/2-2*cell:width*.70, yy=mobile?250:40;
  board.matrix('kernel',K,{x:kx,y:ky,cell,label:'K · 2×3',activeRow:0,color:P.blue,precision:2});
  board.matrix('flat-input',X,{x:xx,y:xy,cell,label:'X_flat · 3×4',activeCol:2,color:P.orange,precision:0});
  board.matrix('flat-output',Y,{x:yx,y:yy,cell,label:'Y_flat · 2×4',precision:2});
  board.rect('selected-output',yx+2*cell,yy,cell-2,cell-2,'none',{stroke:P.blue,'stroke-width':2,'rx':2});
  const cols=['00','01','10','11'];
  cols.forEach((s,i)=>{
    board.text('x-pos-'+i,s,xx+(i+.5)*cell,xy+3*cell+23,{anchor:'middle',size:12,color:P.muted});
    board.text('y-pos-'+i,s,yx+(i+.5)*cell,yy+2*cell+23,{anchor:'middle',size:12,color:P.muted});
  });
  board.text('position-axis','列 → 像素 (h,w)',xx+2*cell,mobile?170:178,{anchor:'middle',size:13,color:P.muted});
  const sy=mobile?387:253, s0=mobile?width*.25-cell:width*.32, s1=mobile?width*.75-cell:width*.70;
  const maps=Y.map(r=>[r.slice(0,2),r.slice(2,4)]);
  maps.forEach((m,c)=>board.matrix('spatial-'+c,m,{x:c?s1:s0,y:sy,cell,label:'Y'+c+' · 2×2',color:c?P.orange:P.blue,precision:2}));
  board.rect('spatial-selected',s0,sy+cell,cell-2,cell-2,'none',{stroke:P.blue,'stroke-width':2,'rx':2});
  const eqY=mobile?201:207;
  const termX=[width/2-110,width/2-30,width/2+50];
  ['3 × 1','2 × '+Number(beta.toFixed(2)),'− 1'].forEach((v,i)=>board.text('term-text-'+i,v,termX[i],eqY,{anchor:'middle',size:16,color:i===1?P.orange:P.ink}));
  board.text('term-plus','+',width/2-70,eqY,{anchor:'middle',size:15,color:P.muted});
  board.text('term-sum','= '+Number(Y[0][2].toFixed(2)),width/2+113,eqY,{anchor:'middle',size:16,color:P.blue});
  board.text('restore','按原列序还原',width/2,mobile?351:236,{anchor:'middle',size:13,color:P.muted});
  const terms=[3,2*beta,-1];
  for(let i=0;i<3;i++) {
    const start=[xx+2.5*cell,xy+(i+.5)*cell];
    const mid=[termX[i],eqY+11];
    const sum=[yx+2.5*cell,yy+cell*.5];
    const dest=[s0+cell*.5,sy+1.5*cell];
    let a,b,t;
    if(progress<.4){a=start;b=mid;t=progress/.4;}
    else if(progress<.72){a=mid;b=sum;t=(progress-.4)/.32;}
    else{a=sum;b=dest;t=(progress-.72)/.28;}
    const q=a.map((v,j)=>v+(b[j]-v)*t);
    board.circle('term-signal-'+i,q[0],q[1],3.5,i===1?P.orange:P.blue);
  }
  board.text('shared','同一 β 跨位置复用 · 不混合相邻像素',width/2,mobile?488:350,{anchor:'middle',size:12,color:P.muted});
  return {kernel:K,flattenedInput:X,flattenedOutput:Y,spatialOutput:maps,terms,selectedPixel:[1,0],selectedOutput:Y[0][2],inputShape:[3,2,2],outputShape:[2,2,2],beta,readingProgress:progress};
}
